{
	double			sum;
	double			high;
	long double		checksum;
	size_t			nonzero;
}	t_density_stats;

typedef struct s_reference
{
	t_btype			type;
	t_density_stats	channel[CHANNELS];
}	t_reference;

typedef struct s_extent_stats
{
	double		side[2];
	double		boundary[2];
	double		sum;
	double		sum_squares;
	size_t		pixels;
	size_t		nonzero;
	bool		invalid;
}	t_extent_stats;

