static void	set_reference_limits(t_fractal *fractal, t_btype type)
{
	if (type == BUDDHA1)
		set_vals(fractal, 0, 0, 0, 50, 500, 5000, &square_complex);
	else
		set_vals(fractal, 20, 55, 55, 350, 500, 3500, &square_complex);
}

static int	setup_case_config_dims(t_fractal *fractal, t_buddha *buddha,
		t_btype type, int workers, int buffers, int width, int height)
{
	memset(fractal, 0, sizeof(*fractal));
	memset(buddha, 0, sizeof(*buddha));
	fractal->width = width;
	fractal->height = height;
	fractal->size = width * height;
	fractal->num_rows = workers;
	fractal->num_cols = 1;
	fractal->bound = 4.0;
	fractal->zoom = 1.2;
	fractal->move_x = -0.21;
	fractal->move_y = 0.0;
	fractal->buffs = buffers;
	fractal->buddha = buddha;
	buddha->type = type;
	buddha->fast = true;
	buddha->n = 2.0;
	buddha->map_n = 1.0;
	buddha->map_adaptive = true;
	buddha->importance_rms = true;
	buddha->square_specialized = true;
	buddha->orbit_cache = true;
	buddha->interior_rejection = true;
	buddha->white_percentile = BUDDHA_WHITE_PERCENTILE;
	buddha->normalization = BUDDHA_NORM_CHANNEL_PERCENTILE;
	buddha->negative_mode = BUDDHA_NEGATIVE_INVERSE;
	buddha->global_exposure = 1.0;
	buddha->hybrid_spill = BUDDHA_HYBRID_SPILL;
	buddha->hybrid_background = BUDDHA_HYBRID_BACKGROUND;
	buddha->hybrid_foreground = BUDDHA_HYBRID_FOREGROUND;
	buddha->nlm_enabled = (buffers > 1);
	buddha->nlm_smooth_var = true;
	buddha->nlm_patch_radius = 1;
	buddha->nlm_search_radius = 2;
	buddha->nlm_kc = 1.0;
	buddha->nlm_noise_scale = 1.0 / (double)buffers;
	buddha->nlm_noise_floor = 1.0 / (255.0 * 255.0);
	buddha->nlm_r_weight = 1.0;
	buddha->nlm_g_weight = 1.0;
	buddha->nlm_b_weight = 1.0;
	fractal->histograms = CHANNELS * buffers;
	if (buddha->nlm_enabled && fractal->histograms < BUDDHA_NLM_MATRICES)
		fractal->histograms = BUDDHA_NLM_MATRICES;
	fractal->threads = malloc((size_t)workers * sizeof(*fractal->threads));
	if (!fractal->threads)
		return (-1);
	set_reference_limits(fractal, type);
	init_matricies(fractal);
	return (0);
}

static int	setup_case_config_size(t_fractal *fractal, t_buddha *buddha,
		t_btype type, int workers, int buffers, int size)
{
	return (setup_case_config_dims(fractal, buddha, type, workers, buffers,
			size, size));
}

static int	setup_case_config(t_fractal *fractal, t_buddha *buddha,
		t_btype type, int workers, int buffers)
{
	return (setup_case_config_size(fractal, buddha, type, workers,
			buffers, TEST_SIZE));
}

static int	setup_case_workers(t_fractal *fractal, t_buddha *buddha,
		t_btype type, int workers)
{
	return (setup_case_config(fractal, buddha, type, workers, 1));
}

static int	setup_case(t_fractal *fractal, t_buddha *buddha, t_btype type)
{
	return (setup_case_workers(fractal, buddha, type, 1));
}

static void	teardown_case(t_fractal *fractal)
{
	free_matrices(fractal);
	free(fractal->threads);
}

static t_density_stats	measure_density(double **density)
{
	t_density_stats	stats;
	int				x;
	int				y;

	memset(&stats, 0, sizeof(stats));
	y = -1;
	while (++y < TEST_SIZE)
	{
		x = -1;
		while (++x < TEST_SIZE)
		{
			stats.sum += density[y][x];
			if (density[y][x] > stats.high)
				stats.high = density[y][x];
			if (density[y][x] != 0.0)
				stats.nonzero++;
			stats.checksum += (long double)density[y][x]
				* (long double)(1 + x + y * TEST_SIZE);
		}
	}
	return (stats);
}

static void	print_stats(t_btype type, int channel, t_density_stats stats)
{
	printf("type=%d channel=%d sum=%.17g high=%.17g "
		"checksum=%.21Lg nonzero=%zu\n", type, channel, stats.sum,
		stats.high, stats.checksum, stats.nonzero);
}

static int	close_enough(long double actual, long double expected)
{
	long double	scale;

	scale = fabsl(expected);
	if (scale < 1.0L)
		scale = 1.0L;
	return (fabsl(actual - expected) <= scale * 1e-12L);
}

static int	matches_reference(t_density_stats actual,
		t_density_stats expected)
{
	return (close_enough(actual.sum, expected.sum)
		&& close_enough(actual.high, expected.high)
		&& close_enough(actual.checksum, expected.checksum)
		&& actual.nonzero == expected.nonzero);
}

static int	run_case(const t_reference *reference, int print_reference)
{
	t_fractal			fractal;
	t_buddha			buddha;
	t_density_stats	stats;
	int					channel;
	int					failed;

	if (setup_case(&fractal, &buddha, reference->type) != 0)
		return (fprintf(stderr, "Buddha regression setup failed\n"), 1);
	failed = 0;
	channel = -1;
	while (++channel < CHANNELS)
	{
		buddha_render_channel(&fractal,
			((int [CHANNELS]){fractal.buddha->min1, fractal.buddha->min2,
				fractal.buddha->min3})[channel],
			((int [CHANNELS]){fractal.buddha->max1, fractal.buddha->max2,
				fractal.buddha->max3})[channel], channel);
		stats = measure_density(fractal.densities[channel]);
		if (print_reference)
			print_stats(reference->type, channel, stats);
		else if (!matches_reference(stats, reference->channel[channel]))
		{
			print_stats(reference->type, channel, stats);
			failed = 1;
		}
	}
	teardown_case(&fractal);
	return (failed);
}

static int	test_tone_mapping(void)
{
	t_buddha	buddha;
	double	values[10] = {10.0, 1.0, 9.0, 2.0, 8.0,
		3.0, 7.0, 4.0, 6.0, 5.0};
	double	sparse[10] = {0.0};
	double	blue_values[4] = {1.0, 4.0, 0.0, 2.0};
	double	green_values[4] = {2.0, 1.0, 0.0, 8.0};
	double	red_values[4] = {0.5, 3.0, 0.0, 1.0};
	double	*blue[1] = {blue_values};
	double	*green[1] = {green_values};
	double	*red[1] = {red_values};
	double	**rgb[3] = {blue, green, red};
	double	*matrix[1];
	double	percentile;
	double	mapped;

	matrix[0] = values;
	percentile = buddha_density_percentile(matrix, 10, 1, 0.8);
	if (percentile != 8.0)
		return (fprintf(stderr, "Unexpected Buddha percentile: %.17g\n",
				percentile), 1);
	sparse[9] = 42.0;
	matrix[0] = sparse;
	percentile = buddha_density_percentile(matrix, 10, 1, 0.8);
	if (percentile != 42.0)
		return (fprintf(stderr, "Sparse Buddha percentile was zero\n"), 1);
	matrix[0] = values;
	mapped = buddha_tone_value(percentile, percentile,
			0.5, 0.2, 0.8, 0.8);
	if (!close_enough(mapped, 1.0L))
		return (fprintf(stderr, "White point did not map to white: %.17g\n",
				mapped), 1);
	mapped = buddha_tone_value(percentile, percentile,
			0.5, 0.2, 1.0, 0.8);
	if (mapped <= 0.0 || mapped >= 1.0)
		return (fprintf(stderr, "Tone edge no longer controls clipping\n"), 1);
	mapped = buddha_tone_value(0.0, percentile, 0.5, 0.2, 0.8, 0.8);
	if (mapped != 0.0)
		return (fprintf(stderr, "Zero density did not map to black\n"), 1);
	mapped = buddha_curve_value(1.0, 10.0, -0.5);
	if (mapped <= 0.0 || mapped >= 1.0
		|| buddha_curve_value(10.0, 10.0, -0.5) != 0.0
		|| buddha_curve_value(0.0, 10.0, -0.5) != 0.0)
		return (fprintf(stderr, "Signed inverse tone curve failed\n"), 1);
	if (buddha_legacy_spill_color(25.0, 100.0, -0.5,
			1.0, 0) != 0x000001FEu
		|| buddha_legacy_spill_color(25.0, 100.0, -0.5,
			1.0, 8) != 0x0001FE00u
		|| buddha_legacy_spill_color(25.0, 100.0, -0.5,
			1.0, 16) != 0x00FE0000u
		|| buddha_legacy_spill_color(0.0, 100.0, -0.5,
			1.0, 0) != 0)
		return (fprintf(stderr, "Legacy channel spill mapping failed\n"), 1);
	if (!close_enough(buddha_adjust_power(0.07, -1.0,
				false, false), 0.02)
		|| !close_enough(buddha_adjust_power(-0.07, 1.0,
				false, false), -0.02)
		|| !close_enough(buddha_adjust_power(-0.01, 1.0,
				false, false), 0.05)
		|| !close_enough(buddha_adjust_power(-0.05, 1.0,
				true, false), -0.04)
		|| !close_enough(buddha_adjust_power(-0.001, 1.0,
				true, true), 0.001)
		|| !close_enough(buddha_adjust_power(-0.2, -1.0,
				false, false), -0.25)
		|| !close_enough(buddha_adjust_power(-0.2, 1.0,
				true, false), -0.19)
		|| !close_enough(buddha_adjust_power(-0.2, 1.0,
				false, true), -0.199))
		return (fprintf(stderr, "Near-zero power adjustment failed\n"), 1);
	rgb[0][0] = blue_values;
	rgb[1][0] = green_values;
	rgb[2][0] = red_values;
	percentile = buddha_density_percentile_rgb(rgb, 4, 1, 0.75);
	if (percentile != 4.0)
		return (fprintf(stderr, "Unexpected linked percentile: %.17g\n",
				percentile), 1);
	memset(&buddha, 0, sizeof(buddha));
	buddha.bpow = 0.4;
	buddha.gpow = 0.5;
	buddha.rpow = 0.6;
	buddha.global_exposure = 1.0;
	buddha.white_percentile = 0.999;
	buddha.normalization = BUDDHA_NORM_CHANNEL_PERCENTILE;
	buddha_tone_store_defaults(&buddha);
	buddha.bpow = -0.4;
	buddha.normalization = BUDDHA_NORM_LEGACY_MAX;
	buddha.negative_mode = BUDDHA_NEGATIVE_SPILL;
	buddha.hybrid_spill = 0.35;
	buddha_tone_swap_alternate(&buddha);
	if (buddha.bpow != 0.4
		|| buddha.normalization != BUDDHA_NORM_CHANNEL_PERCENTILE
		|| buddha.negative_mode != BUDDHA_NEGATIVE_INVERSE
		|| buddha.hybrid_spill != 0.0)
		return (fprintf(stderr, "Tone A/B first swap failed\n"), 1);
	buddha_tone_swap_alternate(&buddha);
	if (buddha.bpow != -0.4
		|| buddha.normalization != BUDDHA_NORM_LEGACY_MAX
		|| buddha.negative_mode != BUDDHA_NEGATIVE_SPILL
		|| buddha.hybrid_spill != 0.35)
		return (fprintf(stderr, "Tone A/B second swap failed\n"), 1);
	buddha_tone_reset(&buddha);
	if (buddha.bpow != 0.4
		|| buddha.normalization != BUDDHA_NORM_CHANNEL_PERCENTILE
		|| buddha.negative_mode != BUDDHA_NEGATIVE_INVERSE
		|| buddha.hybrid_spill != 0.0)
		return (fprintf(stderr, "Tone reset failed\n"), 1);
	return (0);
}

