	buddha.global_exposure = 1.0;
	buddha.negative_mode = BUDDHA_NEGATIVE_HYBRID;
	buddha.hybrid_spill = 0.0;
	buddha.hybrid_background = BUDDHA_HYBRID_BACKGROUND;
	buddha.hybrid_foreground = BUDDHA_HYBRID_FOREGROUND;
	buddha.smootherstep = false;
	buddha_tone_store_defaults(&buddha);
	channel = -1;
	while (++channel < 3)
		fractal.densities[channel][0][1] = 100.0;
