static int	check_aspect_geometry(int width, int height)
{
	t_fractal	fractal;
	t_buddha	buddha;
	t_comps	comps;
	t_complex	first;
	t_complex	last;
	double		expected_scale_ratio;
	double		pixel_scale_x;
	double		pixel_scale_y;
	double		sample_density;
	double		sample_pixel_area;
	int			failed;

	memset(&fractal, 0, sizeof(fractal));
	memset(&buddha, 0, sizeof(buddha));
	fractal.width = width;
	fractal.height = height;
	fractal.size = width * height;
	fractal.zoom = 1.2;
	fractal.buddha = &buddha;
	buddha.n = 2.0;
	buddha.map_n = 1.0;
	comps = set_comps(&fractal, false);
	failed = 0;
	pixel_scale_x = fabs(comps.slopex_to);
	pixel_scale_y = fabs(comps.slopey_to);
	expected_scale_ratio = ((double)(height - 1) / (double)height)
		/ ((double)(width - 1) / (double)width);
	sample_density = comps.samples
		/ fabs(comps.sample_x_span * comps.sample_y_span);
	sample_pixel_area = pixel_scale_x * pixel_scale_y;
	first = buddha_sample_point(comps, 0.0, 0.0);
	last = buddha_sample_point(comps, (double)width, (double)height);
	if (!close_enough(fabsl(comps.slopex_back),
			fabsl(comps.slopey_back))
		|| !close_enough(comps.sample_x_span, comps.x_span)
		|| !close_enough(comps.sample_y_span, comps.y_span)
		|| !close_enough(first.x, comps.sample_x_min)
		|| !close_enough(first.y, comps.sample_y_min)
		|| !close_enough(last.x,
			comps.sample_x_min + comps.sample_x_span)
		|| !close_enough(last.y,
			comps.sample_y_min + comps.sample_y_span)
		|| !close_enough(pixel_scale_x / pixel_scale_y,
			expected_scale_ratio)
		|| !close_enough(sample_density * sample_pixel_area,
			buddha.n * buddha.n))
	{
		fprintf(stderr, "Buddha aspect geometry failed at %dx%d\n",
			width, height);
		failed = 1;
	}
	if ((width >= height && (!close_enough(comps.x_span, 4.0L)
				|| fabsl(comps.y_span) < 4.0L))
		|| (height >= width && (!close_enough(comps.y_span, -4.0L)
				|| comps.x_span < 4.0L)))
	{
		fprintf(stderr, "Buddha aspect span failed at %dx%d\n",
			width, height);
		failed = 1;
	}
	return (failed);
}

static int	check_rectangular_map_symmetry(t_btype type,
		int width, int height)
{
	t_fractal	fractal;
	t_buddha	buddha;
	int			x;
	int			y;
	int			failed;

	if (setup_case_config_dims(&fractal, &buddha, type, 2, 1,
			width, height) != 0)
		return (fprintf(stderr,
				"Rectangular symmetry setup failed\n"), 1);
	buddha.map_n = 2.0;
	buddha.map_adaptive = false;
	set_test_channel(&fractal, 0);
	zero_matrix(fractal.densities[0], width, height);
	buddha_map(&fractal);
	failed = 0;
	y = -1;
	while (++y < height)
	{
		x = -1;
		while (++x < width / 2)
		{
			if (fractal.densities[0][y][x]
				!= fractal.densities[0][y][width - 1 - x])
			{
				failed = 1;
				break ;
			}
		}
		if (failed)
			break ;
	}
	if (failed)
		fprintf(stderr, "Rectangular importance symmetry failed at "
			"%dx%d type %d\n", width, height, type);
	teardown_case(&fractal);
	return (failed);
}

static t_extent_stats	measure_extended_axis(t_fractal *fractal, int channel)
{
	t_extent_stats	stats;
	double			value;
	int				offset;
	int				x;
	int				y;

	memset(&stats, 0, sizeof(stats));
	offset = abs(fractal->height - fractal->width) / 2;
	y = -1;
	while (++y < fractal->height)
	{
		x = -1;
		while (++x < fractal->width)
		{
			value = fractal->densities[channel][y][x];
			if (!isfinite(value) || value < 0.0)
				stats.invalid = true;
			if ((fractal->height > fractal->width
					&& (y < offset || y >= offset + fractal->width))
				|| (fractal->width > fractal->height
					&& (x < offset || x >= offset + fractal->height)))
			{
				stats.side[(fractal->height > fractal->width
						&& y >= offset + fractal->width)
					|| (fractal->width > fractal->height
						&& x >= offset + fractal->height)] += value;
				stats.sum += value;
				stats.sum_squares += value * value;
				stats.pixels++;
				stats.nonzero += (value > 0.0);
			}
			if ((fractal->height > fractal->width
					&& (y == offset - 1
						|| y == offset + fractal->width))
				|| (fractal->width > fractal->height
					&& (x == offset - 1
						|| x == offset + fractal->height)))
				stats.boundary[(fractal->height > fractal->width
						&& y == offset + fractal->width)
					|| (fractal->width > fractal->height
						&& x == offset + fractal->height)] += value;
		}
	}
	return (stats);
}

static int	validate_extended_axis(t_fractal *fractal, int channel,
		char *stage)
{
	t_extent_stats	stats;
	double			variance;

	stats = measure_extended_axis(fractal, channel);
	variance = 0.0;
	if (stats.pixels > 0)
		variance = stats.sum_squares / (double)stats.pixels
			- (stats.sum / (double)stats.pixels)
			* (stats.sum / (double)stats.pixels);
	if (stats.invalid || stats.side[0] <= 0.0 || stats.side[1] <= 0.0
		|| stats.boundary[0] <= 0.0 || stats.boundary[1] <= 0.0
		|| stats.nonzero == 0 || variance <= 0.0)
		return (fprintf(stderr,
				"Rectangular %s coverage failed at %dx%d type %d channel %d\n",
				stage, fractal->width, fractal->height,
				fractal->buddha->type, channel), 1);
	return (0);
}

static int	check_rectangular_render(t_btype type, int width, int height)
{
	t_fractal	fractal;
	t_buddha	buddha;
	int			failed;

	if (setup_case_config_dims(&fractal, &buddha, type, 2, 1,
			width, height) != 0)
		return (fprintf(stderr, "Rectangular Buddha setup failed\n"), 1);
	failed = check_aspect_geometry(width, height);
	buddha_render_channel(&fractal, buddha.min1, buddha.max1, 0);
	failed |= validate_extended_axis(&fractal, 0, "raw");
	teardown_case(&fractal);
	return (failed);
}

static int	check_rectangular_determinism(t_btype type, int width, int height)
{
	t_fractal	fractal;
	t_buddha	buddha;
	double		*reference;
	size_t		bytes;
	int			y;
	int			failed;

	if (setup_case_config_dims(&fractal, &buddha, type, 4, 1,
			width, height) != 0)
		return (fprintf(stderr,
				"Rectangular determinism setup failed\n"), 1);
	bytes = (size_t)fractal.size * sizeof(*reference);
	reference = malloc(bytes);
	if (!reference)
		return (teardown_case(&fractal), 1);
	buddha_render_channel(&fractal, buddha.min1, buddha.max1, 0);
	y = -1;
	while (++y < height)
		memcpy(reference + (size_t)y * (size_t)width,
			fractal.densities[0][y], (size_t)width * sizeof(*reference));
	buddha_render_channel(&fractal, buddha.min1, buddha.max1, 0);
	failed = 0;
	y = -1;
	while (++y < height)
		if (memcmp(reference + (size_t)y * (size_t)width,
				fractal.densities[0][y],
				(size_t)width * sizeof(*reference)) != 0)
			failed = 1;
	if (failed)
		fprintf(stderr, "Rectangular render was not deterministic at "
			"%dx%d type %d\n", width, height, type);
	free(reference);
	teardown_case(&fractal);
	return (failed);
}

static int	check_rectangular_nlm(t_btype type, int width, int height)
{
	t_fractal	fractal;
	t_buddha	buddha;
	int			minimum[CHANNELS];
	int			maximum[CHANNELS];
	int			channel;
	int			failed;

	if (setup_case_config_dims(&fractal, &buddha, type, 2, 3,
			width, height) != 0)
		return (fprintf(stderr, "Rectangular NLM setup failed\n"), 1);
	minimum[0] = buddha.min1;
	minimum[1] = buddha.min2;
	minimum[2] = buddha.min3;
	maximum[0] = buddha.max1;
	maximum[1] = buddha.max2;
	maximum[2] = buddha.max3;
	channel = -1;
	while (++channel < CHANNELS)
		buddha_render_channel(&fractal, minimum[channel],
			maximum[channel], channel);
	failed = validate_extended_axis(&fractal, 0, "raw multibuffer");
	if (buddha_nlm(&fractal) != 0)
		failed = 1;
	else
		failed |= validate_extended_axis(&fractal, 0, "NLM");
	teardown_case(&fractal);
	return (failed);
}

static int	test_aspect_geometry_matrix(void)
{
	static const int	dimensions[][2] = {
		{48, 48}, {60, 48}, {48, 60}, {64, 48}, {48, 64},
		{72, 48}, {48, 72}, {80, 45}, {45, 80}, {96, 48}, {48, 96}
	};
	int				failed;
	size_t			index;

	failed = 0;
	index = 0;
	while (index < sizeof(dimensions) / sizeof(dimensions[0]))
	{
		failed |= check_aspect_geometry(
				dimensions[index][0], dimensions[index][1]);
		index++;
	}
	return (failed);
}

static int	test_rectangular_geometry_and_display(void)
{
	t_fractal	fractal;
	int			x;
	int			y;
	int			failed;

	failed = 0;
	failed |= test_aspect_geometry_matrix();
	failed |= check_rectangular_render(BUDDHA1, 60, 48);
	failed |= check_rectangular_render(BUDDHA1, 48, 96);
	failed |= check_rectangular_render(BUDDHA2, 80, 45);
	failed |= check_rectangular_render(BUDDHA2, 48, 72);
	failed |= check_rectangular_map_symmetry(BUDDHA1, 64, 48);
	failed |= check_rectangular_map_symmetry(BUDDHA1, 48, 64);
	failed |= check_rectangular_map_symmetry(BUDDHA2, 72, 48);
	failed |= check_rectangular_map_symmetry(BUDDHA2, 48, 72);
	failed |= check_rectangular_determinism(BUDDHA1, 72, 48);
	failed |= check_rectangular_determinism(BUDDHA2, 48, 64);
	failed |= check_rectangular_nlm(BUDDHA1, 64, 48);
	failed |= check_rectangular_nlm(BUDDHA2, 48, 64);
	if (!buddha_should_rotate_display(600, 1200, 1080)
		|| buddha_should_rotate_display(1200, 600, 1080)
		|| buddha_should_rotate_display(600, 1080, 1080))
	{
		fprintf(stderr, "Oversized portrait display policy is incorrect\n");
		failed = 1;
	}
	memset(&fractal, 0, sizeof(fractal));
	fractal.display_rotated = true;
	fractal.height_orig = 7;
	x = 1;
	y = 2;
	display_to_render_coordinates(&fractal, &x, &y);
	if (x != 2 || y != 5)
	{
		fprintf(stderr, "Clockwise display coordinate inverse is incorrect\n");
		failed = 1;
	}
	return (failed);
}

