static int	verify_worker_reduction(t_fractal *fractal, int channel,
		int buffer)
{
	double	expected;
	size_t	index;
	int		worker;
	int		x;
	int		y;

	index = 0;
	y = -1;
	while (++y < fractal->height)
	{
		x = -1;
		while (++x < fractal->width)
		{
			expected = 0.0;
			worker = -1;
			while (++worker < fractal->worker_histogram_count)
				expected += fractal->worker_histograms[worker][index];
			if (fractal->densities[channel + buffer * CHANNELS][y][x]
				!= expected)
				return (fprintf(stderr,
						"Worker reduction mismatch at (%d, %d)\n", x, y), 1);
			index++;
		}
	}
	return (0);
}

