static int	test_multibuffer_reduction_and_variance(void)
{
	t_fractal	fractal;
	t_buddha	buddha;
	double		expected;
	int			buffer;
	int			worker;
	int			failed;

	if (setup_case_config(&fractal, &buddha, BUDDHA1, 3, 3) != 0)
		return (fprintf(stderr, "Multibuffer Buddha setup failed\n"), 1);
	failed = 0;
	fractal.hist_num = 0;
	buffer = -1;
	while (++buffer < fractal.buffs)
	{
		worker = -1;
		while (++worker < fractal.worker_histogram_count)
			fractal.worker_histograms[worker][0]
				= (double)(1 + worker + buffer * 10);
		buddha_reduce_worker_histograms(&fractal, buffer);
		failed |= verify_worker_reduction(&fractal, 0, buffer);
	}
	combine_buff_set_var(fractal.densities, 0, fractal.buffs,
		fractal.width, fractal.height);
	expected = 36.0;
	if (fractal.densities[0][0][0] != expected
		|| fractal.densities[3][0][0] != 900.0)
	{
		fprintf(stderr, "Multibuffer mean/variance mismatch: %.17g %.17g\n",
			fractal.densities[0][0][0], fractal.densities[3][0][0]);
		failed = 1;
	}
	teardown_case(&fractal);
	return (failed);
}

