static int	test_importance_capture(void)
{
	t_fractal	fractal;
	t_buddha	buddha;
	double		rgb[3];
	int			channel;
	int			failed;

	if (setup_case(&fractal, &buddha, BUDDHA1) != 0)
		return (fprintf(stderr, "Importance capture setup failed\n"), 1);
	fractal.width_orig = fractal.width;
	fractal.height_orig = fractal.height;
	buddha_importance_begin(&fractal);
	failed = (buddha.importance_values != NULL
			|| buddha.render_pixels != NULL);
	buddha.importance_enabled = true;
	buddha_importance_begin(&fractal);
	if (!buddha.importance_values || !buddha.render_pixels)
		failed = 1;
	channel = -1;
	while (++channel < CHANNELS)
	{
		zero_matrix(fractal.densities[channel],
			fractal.width, fractal.height);
		fractal.densities[channel][0][0] = 100.0;
		fractal.densities[channel][0][1] = 25.0;
		buddha_importance_capture(&fractal, channel);
	}
	if (!buddha.importance_ready
		|| buddha.importance_values[0] != 65535U
		|| buddha.importance_values[1] != 65535U
		|| buddha.importance_values[2] != 65535U
		|| buddha.importance_values[3] == 0U
		|| buddha.importance_values[3] >= 65535U
		|| buddha.importance_values[3] % 257U == 0U
		|| buddha.importance_values[3] != buddha.importance_values[4]
		|| buddha.importance_values[4] != buddha.importance_values[5])
	{
		fprintf(stderr,
			"Importance 16-bit capture was not normalized correctly\n");
		failed = 1;
	}
	buddha.importance_mode = BUDDHA_IMPORTANCE_BLUE;
	buddha_importance_pixel_rgb(&fractal, 0, 0, rgb);
	failed |= rgb[0] != 0.0 || rgb[1] != 0.0 || rgb[2] != 1.0;
	buddha.importance_mode = BUDDHA_IMPORTANCE_GREEN;
	buddha_importance_pixel_rgb(&fractal, 0, 0, rgb);
	failed |= rgb[0] != 0.0 || rgb[1] != 1.0 || rgb[2] != 0.0;
	buddha.importance_mode = BUDDHA_IMPORTANCE_RED;
	buddha_importance_pixel_rgb(&fractal, 0, 0, rgb);
	failed |= rgb[0] != 1.0 || rgb[1] != 0.0 || rgb[2] != 0.0;
	if (failed)
		fprintf(stderr, "Importance channel view selection failed\n");
	free(buddha.importance_values);
	free(buddha.render_pixels);
	buddha.importance_values = NULL;
	buddha.render_pixels = NULL;
	teardown_case(&fractal);
	return (failed);
}

static const char	*find_png_text(png_text *text, int count,
		const char *key)
{
	int	index;

	index = -1;
	while (++index < count)
		if (strcmp(text[index].key, key) == 0)
			return (text[index].text);
	return (NULL);
}

static int	verify_export_metadata(const char *path, int fractal_id,
		const char *specific_key)
{
	png_structp	png;
	png_infop	info;
	png_textp	text;
	const char	*value;
	FILE		*file;
	int			color_type;
	int			bit_depth;
	int			intent;
	int			count;
	int			failed;

	file = fopen(path, "rb");
	if (!file)
		return (fprintf(stderr, "Could not open export regression PNG\n"), 1);
	png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
	info = NULL;
	if (!png)
		return (fclose(file), 1);
	info = png_create_info_struct(png);
	if (!info || setjmp(png_jmpbuf(png)))
		return (png_destroy_read_struct(&png, &info, NULL), fclose(file), 1);
	png_init_io(png, file);
	png_read_info(png, info);
	color_type = png_get_color_type(png, info);
	bit_depth = png_get_bit_depth(png, info);
	count = png_get_text(png, info, &text, NULL);
	failed = color_type != PNG_COLOR_TYPE_RGB || bit_depth != 16;
	failed |= png_get_sRGB(png, info, &intent) == 0;
	value = find_png_text(text, count, "Metadata Version");
	failed |= !value || strcmp(value, "fractol-render-v3") != 0;
	value = find_png_text(text, count, "Fractal");
	failed |= !value || !strstr(value,
			(char *[5]){"", "Mandelbrot", "Julia",
				"Buddhabrot", "Barnsley Fern"}[fractal_id]);
	value = find_png_text(text, count, "Output Size");
	failed |= !value || strcmp(value, "width=2;height=2") != 0;
	value = find_png_text(text, count, "PNG Encoding");
	failed |= !value || !strstr(value, "depth=16")
		|| !strstr(value, "writer=streaming-rows");
	failed |= find_png_text(text, count, specific_key) == NULL;
	if (fractal_id == 3)
	{
		value = find_png_text(text, count, "CLI Baseline");
		failed |= !value || !strstr(value, "--center -0x1.ae147ae147ae1p-3")
			|| !strstr(value, "--zoom 0x1.3333333333333p+0");
		value = find_png_text(text, count, "View");
		failed |= !value || !strstr(value, "center_real=")
			|| !strstr(value, "center_imaginary=");
		value = find_png_text(text, count, "Buddha Tone Mode");
		failed |= !value || !strstr(value, "negative_mode=safe inverse")
			|| !strstr(value, "normalization=channel percentiles");
		value = find_png_text(text, count, "Buddha Hybrid Tone");
		failed |= !value || !strstr(value, "background=B3D38E")
			|| !strstr(value, "foreground=29314F");
		value = find_png_text(text, count, "Buddha Formula");
		failed |= !value || !strstr(value, "orbit_cache=1")
			|| !strstr(value, "orbit_cache_points=512")
			|| !strstr(value, "interior_rejection=1");
		value = find_png_text(text, count, "Buddha Importance View");
		failed |= !value || !strstr(value, "mode=RGB")
			|| !strstr(value,
				"capture=double-log1p-block-average-to-u16");
	}
	png_destroy_read_struct(&png, &info, NULL);
	fclose(file);
	if (failed)
		fprintf(stderr, "Export metadata regression failed for fractal %d\n",
			fractal_id);
	return (failed);
}

