static int	read_png_red16(const char *path, uint16_t *red,
		const char *expected_source)
{
	png_byte	row[6];
	png_structp	png;
	png_infop	info;
	png_textp	text;
	const char	*encoding;
	FILE		*file;
	int			count;

	file = fopen(path, "rb");
	if (!file)
		return (-1);
	png = png_create_read_struct(PNG_LIBPNG_VER_STRING, NULL, NULL, NULL);
	info = NULL;
	if (!png)
		return (fclose(file), -1);
	info = png_create_info_struct(png);
	if (!info || setjmp(png_jmpbuf(png)))
		return (png_destroy_read_struct(&png, &info, NULL), fclose(file), -1);
	png_init_io(png, file);
	png_read_info(png, info);
	if (png_get_bit_depth(png, info) != 16
		|| png_get_color_type(png, info) != PNG_COLOR_TYPE_RGB
		|| png_get_rowbytes(png, info) != sizeof(row))
		return (png_destroy_read_struct(&png, &info, NULL), fclose(file), -1);
	count = png_get_text(png, info, &text, NULL);
	encoding = find_png_text(text, count, "PNG Encoding");
	if (expected_source && (!encoding || !strstr(encoding, expected_source)))
		return (png_destroy_read_struct(&png, &info, NULL), fclose(file), -1);
	png_read_row(png, row, NULL);
	*red = (uint16_t)(((uint16_t)row[0] << 8) | row[1]);
	png_destroy_read_struct(&png, &info, NULL);
	fclose(file);
	return (0);
}

static int	export_red16(t_fractal *fractal, uint16_t *red,
		const char *expected_source)
{
	char		path[] = "/tmp/fractol-16bit-XXXXXX.png";
	png_text	*text;
	int			fd;
	int			failed;

	fd = mkstemps(path, 4);
	if (fd == -1)
		return (-1);
	close(fd);
	text = NULL;
	if (expected_source)
		text = build_fractal_text(fractal);
	if (expected_source && !text)
		return (unlink(path), -1);
	failed = export_png16(path, fractal, text) != 0;
	if (!failed)
		failed = read_png_red16(path, red, expected_source) != 0;
	unlink(path);
	return (failed * -1);
}

