static int	test_16bit_buddha_export(void)
{
	double			blue_value[1];
	double			green_value[1];
	double			red_value[1];
	double			*blue[1];
	double			*green[1];
	double			*red[1];
	double			**densities[3];
	t_fractal		fractal;
	t_buddha		buddha;
	double			rgb[3];
	uint16_t		red16;

	blue_value[0] = 25.0;
	green_value[0] = 25.0;
	red_value[0] = 25.0;
	blue[0] = blue_value;
	green[0] = green_value;
	red[0] = red_value;
	densities[0] = blue;
	densities[1] = green;
	densities[2] = red;
	setup_16bit_buddha(&fractal, &buddha, densities);
	buddha_pixel_rgb(&fractal, 0, 0, rgb);
	if (!close_enough(rgb[0], 0.5L))
		return (fprintf(stderr, "Buddha tone was quantized before export\n"), 1);
	if (export_red16(&fractal, &red16, NULL) != 0)
		return (fprintf(stderr, "16-bit Buddha export failed\n"), 1);
	if (red16 != 32768 || red16 % 257 == 0)
		return (fprintf(stderr,
				"16-bit Buddha export was reduced to replicated 8-bit\n"), 1);
	buddha.filter = true;
	buddha.ftype = ADJUST;
	buddha.flevel = 3;
	if (export_red16(&fractal, &red16,
			"source=density-double-tone-adjust") != 0 || red16 != 49151)
		return (fprintf(stderr,
				"16-bit Buddha adjustment export failed\n"), 1);
	buddha.ftype = GAUSS;
	buddha.flevel = 5;
	if (export_red16(&fractal, &red16,
			"source=density-double-tone-gaussian") != 0 || red16 != 32768)
		return (fprintf(stderr,
				"16-bit Buddha Gaussian export failed\n"), 1);
	buddha.filter = false;
	buddha.negative_mode = BUDDHA_NEGATIVE_HYBRID;
	buddha.bpow = -0.2;
	buddha.gpow = -0.2;
	buddha.rpow = -0.2;
	buddha.hybrid_spill = 0.2;
	buddha.hybrid_background = BUDDHA_HYBRID_BACKGROUND;
	buddha.hybrid_foreground = BUDDHA_HYBRID_FOREGROUND;
	buddha.tone_default.power[0] = 0.41;
	buddha.tone_default.power[1] = 0.39;
	buddha.tone_default.power[2] = 0.34;
	buddha.tone_default.exposure[0] = 1.0;
	buddha.tone_default.exposure[1] = 1.0;
	buddha.tone_default.exposure[2] = 1.0;
	buddha_pixel_rgb(&fractal, 0, 0, rgb);
	red16 = (uint16_t)floor(rgb[0] * 65535.0 + 0.5);
	if (red16 % 257 == 0)
		return (fprintf(stderr, "Hybrid tone remained byte-quantized\n"), 1);
	return (0);
}

